def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }
    token_pattern = re.compile(
        r"[0-9]+|[A-Z]+[0-9]*|<>|<=|>=|[()+*/,:=<>-]"
    )

    def integer(text):
        text = text.strip()
        sign = 1
        if text[0] in "+-":
            if text[0] == "-":
                sign = -1
            text = text[1:]

        # Small chunks also support literals beyond Python's digit limit.
        result = 0
        for start in range(0, len(text), 9):
            chunk = text[start:start + 9]
            result = result * (10 ** len(chunk)) + int(chunk)
        return sign * result

    def parse(formula):
        operands = []
        operators = []
        expect_operand = True

        def reduce_operator():
            operator = operators.pop()
            if operator == "neg":
                operands.append(("neg", operands.pop()))
            else:
                right = operands.pop()
                left = operands.pop()
                operands.append((operator, left, right))

        for match in token_pattern.finditer(formula):
            token = match.group()

            if token[0].isdigit():
                operands.append(integer(token))
                expect_operand = False

            elif token in functions:
                operators.append(token)
                expect_operand = True

            elif token[0].isalpha():
                operands.append(token)
                expect_operand = False

            elif token == "(":
                operators.append(("(", len(operands)))
                expect_operand = True

            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                expect_operand = True

            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                _, start = operators.pop()

                if operators and operators[-1] in functions:
                    function = operators.pop()
                    arguments = tuple(operands[start:])
                    del operands[start:]
                    operands.append((function, arguments))

                expect_operand = False

            else:
                operator = "neg" if token == "-" and expect_operand else token
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and operators[-1] in precedence
                    and (
                        precedence[operators[-1]] > precedence[operator]
                        or (
                            precedence[operators[-1]] == precedence[operator]
                            and operator != "neg"
                        )
                    )
                ):
                    reduce_operator()
                operators.append(operator)
                expect_operand = True

        while operators:
            reduce_operator()

        return operands[0]

    def argument_values(arguments):
        for argument in arguments:
            if isinstance(argument, tuple) and argument[0] == ":":
                first, last = argument[1], argument[2]
                col1, col2 = ord(first[0]), ord(last[0])
                row1, row2 = int(first[1:]), int(last[1:])

                for row in range(min(row1, row2), max(row1, row2) + 1):
                    for col in range(min(col1, col2), max(col1, col2) + 1):
                        name = chr(col) + str(row)
                        if name in cells:
                            yield name
            else:
                yield argument

    def binary(operator, left, right):
        if operator == "+":
            return left + right
        if operator == "-":
            return left - right
        if operator == "*":
            return left * right
        if operator == "/":
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if operator == "=":
            return left == right
        if operator == "<>":
            return left != right
        if operator == "<":
            return left < right
        if operator == "<=":
            return left <= right
        if operator == ">":
            return left > right
        return left >= right

    cache = {}
    active = set()

    for root in cells:
        if root in cache:
            continue

        tasks = [("cell", root)]
        value = 0

        while tasks:
            task = tasks.pop()
            action = task[0]

            if action == "cell":
                name = task[1]
                if name in cache:
                    value = cache[name]
                elif name not in cells:
                    value = 0
                elif name in active:
                    value = "#CYCLE!"
                else:
                    content = cells[name].strip()
                    if not content.startswith("="):
                        value = integer(content)
                        cache[name] = value
                    else:
                        expression = parse(content[1:])
                        active.add(name)
                        tasks.append(("store", name))
                        tasks.append(("eval", expression))

            elif action == "store":
                name = task[1]
                cache[name] = value
                active.remove(name)

            elif action == "eval":
                node = task[1]

                if isinstance(node, int):
                    value = node
                elif isinstance(node, str):
                    tasks.append(("cell", node))
                else:
                    operator = node[0]

                    if operator == "neg":
                        tasks.append(("negate",))
                        tasks.append(("eval", node[1]))

                    elif operator == "IF":
                        condition, then_branch, else_branch = node[1]
                        tasks.append(("choose", then_branch, else_branch))
                        tasks.append(("eval", condition))

                    elif operator in functions:
                        iterator = argument_values(node[1])
                        initial = 0 if operator == "SUM" else None
                        tasks.append(("next_arg", operator, iterator, initial))

                    else:
                        tasks.append(("left_done", operator, node[2]))
                        tasks.append(("eval", node[1]))

            elif action == "negate":
                if not isinstance(value, str):
                    value = -value

            elif action == "left_done":
                if not isinstance(value, str):
                    tasks.append(("right_done", task[1], value))
                    tasks.append(("eval", task[2]))

            elif action == "right_done":
                if not isinstance(value, str):
                    value = binary(task[1], task[2], value)

            elif action == "choose":
                if not isinstance(value, str):
                    branch = task[1] if value else task[2]
                    tasks.append(("eval", branch))

            elif action == "next_arg":
                _, function, iterator, accumulated = task
                try:
                    argument = next(iterator)
                except StopIteration:
                    value = 0 if accumulated is None else accumulated
                else:
                    tasks.append(("arg_done", function, iterator, accumulated))
                    tasks.append(("eval", argument))

            elif action == "arg_done":
                if not isinstance(value, str):
                    _, function, iterator, accumulated = task
                    if function == "SUM":
                        accumulated += value
                    elif accumulated is None:
                        accumulated = value
                    elif function == "MIN":
                        accumulated = min(accumulated, value)
                    else:
                        accumulated = max(accumulated, value)

                    tasks.append(("next_arg", function, iterator, accumulated))

    return {name: cache[name] for name in cells}
